package com.soumyajit.gradlemc.investigation;
public final class InvestigationStateMachine { private InvestigationStateMachine(){} public static void requireTransition(InvestigationState from, InvestigationState to){if(from==null||to==null||!((from==InvestigationState.CREATED&&(to==InvestigationState.RUNNING||to==InvestigationState.CANCELLED||to==InvestigationState.FAILED))||(from==InvestigationState.RUNNING&&(to==InvestigationState.COMPLETED||to==InvestigationState.COMPLETED_WITH_LIMITATIONS||to==InvestigationState.CANCELLED||to==InvestigationState.FAILED))))throw new IllegalStateException("Illegal investigation transition: "+from+" -> "+to);}}
